def searchNearlySorted(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if mid > lo and nums[mid - 1] == target:
            return mid - 1
        if mid < hi and nums[mid + 1] == target:
            return mid + 1
        if nums[mid] < target:
            lo = mid + 2
        else:
            hi = mid - 2
    return -1
